sited.script:

    // 動態解析「標籤頁」的函式
    function tags_parse(url, html) {
        var $ = cheerio.load(html);
        var list = [];
        // 遍歷 ID 為 nav 的主導覽列下的每一個分組
        $('li.has-child').each(function() {
            var $$ = cheerio.load($(this).html());
			var groupElement = $(this);
            var groupName = $$('a').first().text().trim();
            if (groupName.match(/列表|更多站点/)) return;
            // 在該分組下，尋找所有子項目連結
            $$('ul li a').each(function() {
                var itemElement = $$(this);
                var itemTitle = itemElement.text().trim();
                var itemUrl = itemElement.attr('href');
                if (itemTitle.match(/热门女演员/)) return;
                if (itemUrl && itemTitle) {
                    if (!groupName.match(/观看JAV/)) {
                        list.push({
                            group: gbk2big5.traditionalized(groupName),
                            title: gbk2big5.traditionalized(itemTitle),
                            url: "https://123av.com/zh/"+itemUrl+"?page=@page&sort=trending"
                        });
                    }
                    else {
                        list.push({
                            group: gbk2big5.traditionalized(groupName),
                            title: gbk2big5.traditionalized(itemTitle),
                            url: "https://123av.com/zh/"+itemUrl+"?page=@page"
                        });
                    }
                }
            });
        });
        $('.star a').each(function() {
            var $$ = cheerio.load($(this).html());
            list.push({
                group: gbk2big5.traditionalized("本週熱門女優"),
                title: gbk2big5.traditionalized($$('.name').text()),
                url: "https://123av.com/zh/"+$(this).attr('href')+"?page=@page&sort=most_viewed_week"
            });
        });
        return JSON.stringify(list);
    }

    function home_list_parse(url, html){
        var $ = cheerio.load(html);
        var list = [];

        $('section').each(function(){
            var $$ = cheerio.load($(this).html());
            var group_name = gbk2big5.traditionalized($$("h2").text().trim());
            $$('div.box-item').each(function() {
                var $$$ = cheerio.load($(this).html());
                if ($$$("div.detail a").attr('href')) list.push({group: group_name,url:"https://123av.com/zh/"+$$$("div.detail a").attr('href'), name:gbk2big5.traditionalized($$$("div.detail a").text()), logo:$$$("img").attr('data-src')});
            });
        });


        return JSON.stringify(list);
    }

    // 核心的「內容列表」解析函式
    function list_parse(url, html){
        var $ = cheerio.load(html);
        var list = [];

        $('section div.box-item').each(function() {
            var $$ = cheerio.load($(this).html());
            if ($$("div.detail a").attr('href')) list.push({url:"https://123av.com/zh/"+$$("div.detail a").attr('href'), name:gbk2big5.traditionalized($$("div.detail a").text()), logo:$$("img").attr('data-src')})
        });

        return JSON.stringify(list);
    }

    function section_parse(url, html) {
        return JSON.stringify({type:"webview", data: url});
    }

sited.WebViewInjection:

            javascript:(function() {
    // 定義一個變數來儲存定時器的 ID，以便我們可以停止它
    let intervalId = null;

    // 1. 定義您的核心邏輯（保持不變）
    function runInjection() {
        try {
            // 您的原始腳本邏輯開始
            var player = document.getElementById('player');
            var scenes = document.getElementById('scenes');
            var title = document.querySelector('.d-flex h1');
            var content = document.querySelector('.content');

            if (player) {
                document.body.style.visibility = 'hidden';

                var current = player;
                while (current && current.tagName !== 'BODY') {
                    current.style.visibility = 'visible';
                    var siblings = Array.from(current.parentNode.children);
                    siblings.forEach(function(sibling) {
                        if (sibling !== current) {
                            sibling.style.display = 'none';
                        }
                    });
                    current = current.parentElement;
                }

                if (scenes) {
                    var current = scenes;
                    while (current && current.tagName !== 'BODY') {
                        current.style.visibility = 'visible';
                        current.style.display = 'block';
                        current = current.parentElement;
                    }
                } else {
                    return false;
                }
                if (title) {
                    var current = title;
                    while (current && current.tagName !== 'BODY') {
                        current.style.visibility = 'visible';
                        current.style.display = 'block';
                        current = current.parentElement;
                    }
                } else {
                    return false;
                }
                if (content) {
                    var current = content;
                    while (current && current.tagName !== 'BODY') {
                        current.style.visibility = 'visible';
                        current.style.display = 'block';
                        current = current.parentElement;
                    }
                } else {
                    return false;
                }

                document.body.style.visibility = 'visible';
                document.body.style.margin = '0';
                document.body.style.padding = '0';

                // 成功找到並處理元素後，返回 true
                return true;
            } else {
                // 如果 'player' 還沒找到，返回 false 繼續輪詢
                return false;
            }
        } catch (e) {
            // 發生其他錯誤時，返回 false 繼續輪詢
            return false;
        }
    }

    // 2. 啟動定時器，每 1000 毫秒（1 秒）執行一次檢查
    intervalId = setInterval(function() {
        if (runInjection()) {
            // 3. 如果 runInjection() 成功返回 true，則清除定時器
            clearInterval(intervalId);
        }
    }, 1000); // 1000 毫秒 = 1 秒

    // 可選：設定一個最大時限，防止無限輪詢
    setTimeout(function() {
        if (intervalId !== null) {
            clearInterval(intervalId);
            console.log("Injection: Max timeout reached. Stopping interval.");
        }
    }, 15000); // 例如，最多只嘗試 15 秒

})();
